def tally(words):
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    return counts

data = ["a", "b", "a"]
first = tally(data)
second = tally(data)
print(first)                    # {'a': 2, 'b': 1}
print(data)                     # ['a', 'b', 'a']  — unchanged
print(first is second)          # False — a fresh dictionary per call
first["z"] = 99
print(second)                   # {'a': 2, 'b': 1}  — unaffected

